 if($method==='GET'&&$action==='export'){role('admin','super_admin');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="accommodation-report.csv"');$f=fopen('php://output','w');fputcsv($f,['Student','Matriculation','Eligibility','Hostel','Room','Bed','Status']);foreach($pdo->query("SELECT sp.first_name || ' ' || sp.last_name,sp.matric_no,sp.eligibility,h.name,rm.room_number,b.bed_label,a.status FROM allocations a JOIN student_profiles sp ON sp.user_id=a.student_user_id JOIN bed_spaces b ON b.id=a.bed_space_id JOIN rooms rm ON rm.id=b.room_id JOIN hostels h ON h.id=rm.hostel_id") as $row)fputcsv($f,$row);exit;}
